 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Each 6 draws the full NW-SE diagonal that passes through it.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                d = c - r
                for rr in range(h):
                    cc = rr + d
                    if 0 <= cc < w:
                        out[rr][cc] = 6

    # Connect 1 markers on a common diagonal. Original 6 cells stay 6;
    # generated 6 diagonal cells are overwritten by the connecting 1 line.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                for k in range(abs(r2-r1) + 1):
                    rr, cc = r1 + k*dr, c1 + k*dc
                    if grid[rr][cc] != 6:
                        out[rr][cc] = 1
    return out

